select *, first_value(stock_qty, true) over (partition by category, brand order by cost, id rows between unbounded preceding and current row) as first_known_stock_qty, corr(price, cost) over (partition by supplier_id) as corr_price_cost, corr(cost, stock_qty) over (partition by brand) as corr_cost_stock_qty, lag(stock_qty, 1) over (partition by brand order by price, id) as prev_stock_qty, sum(cost) over (partition by category order by stock_qty, id rows between unbounded preceding and current row) as cumulative_cost from products
